# Counts describe complete original syntax, not executed iteration counts.
CALL_VIEWS = {
    '_scene_refresh_call_fields': {
        'refresh_gameplay_scene_fields': 1, 'wait_for_scene_sound_byte_fields': 1,
        'select_sound_command_from_scene_fields': 1, 'draw_overlay_frame_fields': 1,
        'resume_pending_sound_fields': 1, 'enqueue_sound_command_fields': 1,
        'play_scripted_scene_fields': 1},
    'load_gameplay_scene_fields': {'_scene_refresh_call_fields': 9},
    'select_sound_command_from_scene_fields': {'_scene_refresh_call_fields': 1},
    'resume_pending_sound_fields': {'_scene_refresh_call_fields': 1},
    'draw_overlay_frame_fields': {'_scene_refresh_call_fields': 3},
}
WAIT_VIEWS = {
    'refresh_gameplay_scene_fields': ("memory.state.progress(edge)", '_scene_load_wait(memory.state, frame, edge)'),
    'wait_for_scene_sound_byte_fields': ("memory.state.progress('scene-sound-byte')", "_scene_load_wait(memory.state, frame, 'scene-sound-byte')"),
    'enqueue_sound_command_fields': ("memory.state.progress('sound-bus-acquire')", "_scene_load_wait(memory.state, frame, 'sound-bus-acquire')"),
}


def _dump(node):
    return ast.dump(node, include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code, name) for name in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value for value in code.co_consts),)


def _function_code(module_code, name):
    matches = [value for value in module_code.co_consts if type(value) is CodeType
        and value.co_name == name and value.co_qualname == name]
    if len(matches) != 1:
        raise ValueError('one complete top-level scene-load source owner required')
    return matches[0]


def _cooperative_service_tree(original_tree):
    """Lift eight complete original owners with full function/module inverses."""
    names = set(CALL_VIEWS) | set(WAIT_VIEWS)
    if set(EXPECTED_ORIGINAL_ASTS) != names:
        raise ValueError('exact complete scene-load source inventory required')
    result = copy.deepcopy(original_tree)
    inverses = {}
    for index, node in enumerate(original_tree.body):
        if not isinstance(node, ast.FunctionDef) or node.name not in names:
            continue
        if node.name in inverses or _dump(node) != EXPECTED_ORIGINAL_ASTS[node.name]:
            raise ValueError('complete reviewed scene-load owner changed: ' + node.name)
        if any(isinstance(item, (ast.Yield, ast.YieldFrom)) for item in ast.walk(node)):
            raise ValueError('original scene-load owner must be synchronous')
        wanted = CALL_VIEWS.get(node.name, {})
        counts = {name: 0 for name in wanted}
        progress = WAIT_VIEWS.get(node.name)
        old_wait = ast.parse(progress[0]).body[0] if progress else None
        new_wait = ast.parse('frame = (yield ' + progress[1] + ')').body[0] if progress else None
        wait_count = []

        class Lift(ast.NodeTransformer):
            def visit_Call(self, item):
                item = self.generic_visit(item)
                if isinstance(item.func, ast.Name) and item.func.id in wanted:
                    name = item.func.id
                    counts[name] += 1
                    if name == 'play_scripted_scene_fields':
                        item.func.id = '_scene_load_scripted_program'
                    return ast.copy_location(ast.YieldFrom(value=item), item)
                return item

            def visit_Expr(self, item):
                if old_wait is not None and _dump(item) == _dump(old_wait):
                    wait_count.append(item)
                    return ast.copy_location(copy.deepcopy(new_wait), item)
                return self.generic_visit(item)

        lifted = Lift().visit(copy.deepcopy(node))
        if counts != wanted or len(wait_count) != (1 if progress else 0):
            raise ValueError('exact complete scene-load substitutions required: ' + node.name)

        class Inverse(ast.NodeTransformer):
            def visit_YieldFrom(self, item):
                call = self.generic_visit(item.value)
                if not isinstance(call, ast.Call) or not isinstance(call.func, ast.Name):
                    raise ValueError('only finite named scene-load child views are admitted')
                if call.func.id == '_scene_load_scripted_program':
                    call.func.id = 'play_scripted_scene_fields'
                if call.func.id not in wanted:
                    raise ValueError('unknown scene-load cooperative child')
                return ast.copy_location(call, item)

            def visit_Assign(self, item):
                if new_wait is not None and _dump(item) == _dump(new_wait):
                    return ast.copy_location(copy.deepcopy(old_wait), item)
                return self.generic_visit(item)

        inverse = Inverse().visit(copy.deepcopy(lifted))
        if _dump(inverse) != _dump(node):
            raise ValueError('whole scene-load function inverse differs: ' + node.name)
        result.body[index] = lifted
        inverses[index] = inverse
    if len(inverses) != len(names):
        raise ValueError('all eight original scene-load owners required')
    restored = copy.deepcopy(result)
    for index, inverse in inverses.items():
        restored.body[index] = inverse
    if _dump(restored) != _dump(original_tree):
        raise ValueError('entire original scene-service module inverse differs')
    ast.fix_missing_locations(result)
    return result


def _make_load_program(state, frame, entry_pc=67372):
    """Compile complete source context, not imports or original business execution."""
    if type(entry_pc) is not int or entry_pc not in (67372, 44872):
        raise ValueError('only actual whole1072C load orAF48 refresh entry is admitted')
    from . import business_services
    source = inspect.getsource(business_services)
    tree = ast.parse(source, filename=business_services.__file__)
    plain = compile(tree, business_services.__file__, 'exec', dont_inherit=True)
    for name in EXPECTED_ORIGINAL_ASTS:
        original = getattr(business_services, name)
        if type(original) is not FunctionType or original.__module__ != business_services.__name__ or original.__name__ != name or (original.__globals__ is not vars(business_services)) or (original.__closure__ is not None) or inspect.isgeneratorfunction(original) or (_code_shape(_function_code(plain, name)) != _code_shape(original.__code__)):
            raise ValueError('actual complete unwrapped scene-load owner required: ' + name)
    derived = compile(_cooperative_service_tree(tree), business_services.__file__, 'exec', dont_inherit=True)
    namespace = dict(vars(business_services))
    if any((name in namespace for name in ('_scene_load_wait', '_scene_load_scripted_program'))):
        raise ValueError('private cooperative scene-load names must not shadow business bindings')
    namespace.update(_scene_load_wait=_scene_load_wait, _scene_load_scripted_program=_scene_load_scripted_program)
    for name in EXPECTED_ORIGINAL_ASTS:
        original = getattr(business_services, name)
        view = FunctionType(_function_code(derived, name), namespace, name, original.__defaults__, None)
        view.__kwdefaults__ = original.__kwdefaults__
        view.__annotations__ = dict(original.__annotations__)
        if not inspect.isgeneratorfunction(view) or view.__closure__ is not None:
            raise ValueError('every finite scene-load view must retain its original complete arguments')
        namespace[name] = view
    from .contexts_services import SceneRefreshMemory
    return namespace[{67372: 'load_gameplay_scene_fields', 44872: 'refresh_gameplay_scene_fields'}[entry_pc]](SceneRefreshMemory(state), frame)


@dataclass(frozen=True)
class GameplaySceneWait:
    """Original polling point; explicit IRQ, VDP edge or sound-bus progress only."""
    state: SceneState
    frame: FirstDeploymentFrame
    status_word: int
    event: str
    poll: int

    @property
    def stage(self):
        return 'original_gameplay_scene_load'

    @property
    def needs_interrupt(self):
        return self.event == 'scene-sound-byte'

    def validate(self):
        checked_state(self.state)
        _movement_frame(self.state, self.frame)
        if (self.event, self.poll) not in (('scene-sound-byte', 33740), ('vblank-end', 44876), ('vblank-start', 44892), ('sound-bus-acquire', 32920), ('vdp-dma', 26758), ('vdp-dma', 26874), ('vblank-start', 3480)):
            raise ValueError('actual finite scene-load polling point and external event required')
        uint(self.status_word, 16)
        if self.state.sr != self.status_word or self.frame.status != self.status_word & 31:
            raise ValueError('scene-load full SR and software CCR-X disagree')
        return self


def _scene_load_wait(state, frame, event):
    polls = {'scene-sound-byte': 0x83CC, 'vblank-end': 0xAF4C,
        'vblank-start': 0xAF5C, 'sound-bus-acquire': 0x8098}
    if event not in polls:
        raise ValueError('only the four original scene-load external waits are admitted')
    return GameplaySceneWait(state, frame, state.sr, event, polls[event]).validate()


def _scene_load_scripted_program(state, frame):
    """The original10784 LONG already exists; no second physical CALL is added."""
    session = PersistentScriptedSceneSession(state, frame)
    current = session.start()
    while type(current) is ScriptedSceneWait:
        returned = yield current
        current = session.resume(returned, current.poll)
    return current


class GameplaySceneLoadSession:
    """Whole1072C invocation, including all original setup, playback and cleanup.

    IRQ returns and externally supplied device events are separate operations.
    The object never clears a phase, changes mode, runs a clock or pops its
    incoming caller-owned LONG. A failed/completed invocation cannot restart.
    """
    entry_pc = 0x1072C

    def __init__(self, state: SceneState, frame: FirstDeploymentFrame):
        self.state = checked_state(state)
        self.entry = _movement_frame(state, frame)
        if frame.status != (state.sr & 31):
            raise ValueError('scene-load entry must retain complete full SR/CCR-X')
        self._thread = threading.get_ident()
        self._program = _make_load_program(state, frame, self.entry_pc)
        self._started = self._complete = self._failed = False
        self.waiting = self.result = None
        self.suspensions = 0

    @property
    def complete(self):
        return self._complete

    def _check_live(self):
        if threading.get_ident() != self._thread:
            raise ValueError('one original scene-load invocation must remain on its owning thread')
        if not self._started or self._complete or self._failed or self.waiting is None:
            raise ValueError('one live suspended whole1072C invocation required')

    def _take(self, returned=None):
        if threading.get_ident() != self._thread:
            raise ValueError('one original scene-load invocation must remain on its owning thread')
        try:
            waiting = next(self._program) if returned is None else self._program.send(returned)
        except StopIteration as finished:
            self.result = _movement_frame(self.state, finished.value)
            if self.result.stack_cursor.base != self.entry.stack_cursor.base:
                self._failed = True
                raise Boundary('whole1072C did not restore its actual saved WORD/CALL stack')
            if self.result.status != (self.state.sr & 31):
                self._failed = True
                raise ValueError('scene-load completion SR and frame CCR-X disagree')
            self._complete = True
            self.waiting = None
            return self.result
        except BaseException:
            self._failed = True
            raise
        if type(waiting) not in (GameplaySceneWait, ScriptedSceneWait) or waiting.state is not self.state:
            self._failed = True
            raise ValueError('one actual same-Scene load or nested scripted-scene wait required')
        self.waiting = waiting.validate()
        self.suspensions += 1
        return self.waiting

    def start(self):
        if self._started:
            raise ValueError('cannot replay original1072C setup/saved sound WORD')
        self._started = True
        return self._take()

    def resume_interrupt(self, returned: FirstDeploymentFrame, pc: int):
        self._check_live()
        waiting = self.waiting
        if type(waiting) is GameplaySceneWait and not waiting.needs_interrupt:
            raise ValueError('this actual scene-load point needs a device event, not a fabricated IRQ')
        returned = _movement_frame(self.state, returned)
        uint(pc, 32)
        if pc != waiting.poll:
            raise MovementContinuationBoundary(pc, returned, 'IRQ did not RTE to the actual scene-load poll')
        if returned.stack_cursor.base != waiting.frame.stack_cursor.base:
            raise Boundary('IRQ did not preserve the original scene-load physical stack')
        if self.state.sr != waiting.status_word or returned.status != (self.state.sr & 31):
            raise ValueError('IRQ must restore actual scene-load complete SR and CCR-X')
        return self._take(returned)

    def resume_device(self, event: str):
        self._check_live()
        waiting = self.waiting
        if type(waiting) is not GameplaySceneWait or waiting.needs_interrupt or event != waiting.event:
            raise ValueError('the exact explicitly supplied scene-load device event is required')
        if self.state.sr != waiting.status_word:
            raise ValueError('external device progress cannot alter the saved software SR')
        # The caller has supplied actual device progress. Original code rereads
        # that device on continuation; it does not receive a successful result.
        return self._take(waiting.frame)


class GameplaySceneRefreshSession(GameplaySceneLoadSession):
    """The same whole service views, entered at actualAF48, not1072C."""
    entry_pc = 0xAF48
